class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> res;
        string cur;
        auto isValid = [&]() -> bool {
            int bal = 0;
            for (char c : cur) {
                if (c == '(') bal++;
                else bal--;
                if (bal < 0) return false;
            }
            return bal == 0;
        };
        function<void()> dfs = [&]() {
            if ((int)cur.size() == 2 * n) {
                if (isValid()) res.push_back(cur);
                return;
            }
            cur.push_back('(');
            dfs();
            cur.pop_back();
            cur.push_back(')');
            dfs();
            cur.pop_back();
        };
        dfs();
        return res;
    }
};

