        res = []
        cur = []
        def is_valid() -> bool:
            bal = 0
            for c in cur:
                if c == '(':
                    bal += 1
                else:
                    bal -= 1
                if bal < 0:
                    return False
            return bal == 0
        def dfs():
            if len(cur) == 2 * n:
                if is_valid():
                    res.append(''.join(cur))
                return
            cur.append('(')
            dfs()
            cur.pop()
            cur.append(')')
            dfs()
            cur.pop()
        dfs()
        return res

