class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> res = new ArrayList<>();
        dfs(res, new StringBuilder(), 0, n);
        return res;
    }
    private void dfs(List<String> res, StringBuilder cur, int pos, int n) {
        if (pos == 2 * n) {
            if (isValid(cur)) res.add(cur.toString());
            return;
        }
        cur.append('(');
        dfs(res, cur, pos + 1, n);
        cur.deleteCharAt(cur.length() - 1);
        cur.append(')');
        dfs(res, cur, pos + 1, n);
        cur.deleteCharAt(cur.length() - 1);
    }
    private boolean isValid(StringBuilder s) {
        int bal = 0;
        for (int i = 0; i < s.length(); ++i) {
            if (s.charAt(i) == '(') bal++;
            else bal--;
            if (bal < 0) return false;
        }
        return bal == 0;
    }
}

