class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<vector<string>> dp(n + 1);
        dp[0].push_back(string());
        for (int k = 1; k <= n; ++k) {
            for (int i = 0; i < k; ++i) {
                for (auto &left : dp[i]) {
                    for (auto &right : dp[k - 1 - i]) {
                        string s;
                        s.push_back('(');
                        s += left;
                        s.push_back(')');
                        s += right;
                        dp[k].push_back(s);
                    }
                }
            }
        }
        return dp[n];
    }
};

